parts.script:
// ctx.inputs: one entry per incoming connector this tick -- log the connector type
// and the SENDING part's own type, without hardcoding which neighbor it is.
for (const inp of ctx.inputs) {
  ctx.log(`IN  <- "${inp.fromLabel}" (${inp.fromPartType}) via a '${inp.connector.connectorType}' connector`);
}

// ctx.outputs: one entry per OUTGOING connector of this part -- purely structural
// (no per-connector value here, since one script return broadcasts identically to
// every outgoing connector). Log the connector type and the RECEIVING part's type.
for (const out of ctx.outputs) {
  ctx.log(`OUT -> "${out.toLabel}" (${out.toPartType}) via a '${out.connector.connectorType}' connector`);
}

return {
  value: { inputCount: ctx.inputs.length, outputCount: ctx.outputs.length },
  state: {},
  leftBadge: { text: `${ctx.inputs.length} in / ${ctx.outputs.length} out`, color: '#2f8f4e' },
};
